using Astrea.BattleActions;
using FMODUnity;
using LittleLeo;
using LittleLeo.Events;
using NaughtyAttributes;
using TMPro;
using UnityEngine;

namespace Astrea;

public class PurifyCorruptTextFeedback : FeedbackInstance
{
	private const string blockedID = "Blocked";

	[Header("Purify Corrupt Movement")]
	[SerializeField]
	private float zoomAmount;

	[SerializeField]
	private float zoomDuration;

	[SerializeField]
	private AnimationCurve zoomCurve;

	[Header("Left Right Movement")]
	[SerializeField]
	private RangedFloat leftRightMovementRangedFloat;

	[SerializeField]
	private AnimationCurve leftRightMovementCurve;

	[Header("Purify Corrupt VFX")]
	[SerializeField]
	private FloatFloatEvent OnScreenShake;

	[SerializeField]
	private GameObject purifyVFX;

	[SerializeField]
	private GameObject corruptVFX;

	[Header("Purify Corrupt Battle Actions")]
	[SerializeField]
	private PurifyAction purifyAction;

	[SerializeField]
	private CorruptAction corruptAction;

	[Header("Block Components")]
	[SerializeField]
	private bool blockFeedback;

	[SerializeField]
	[ShowIf("blockFeedback")]
	private TextMeshProUGUI blockAmountFeedbackText;

	[Header("SFX")]
	[SerializeField]
	private EventReference purifyBlockedSFX;

	[SerializeField]
	private EventReference corruptionBlockedSFX;

	public void PlayPurifyCorruptFeedback(int amount, bool purify, Vector3 unitPosition, FeedbackDirectionEnum feedbackDirectionEnum)
	{
		SetupPurifyCorruptFeedback(amount, purify);
		SpawnVFX(purify, unitPosition);
		PlayFeedback(unitPosition, feedbackDirectionEnum);
	}

	private void SetupPurifyCorruptFeedback(int amount, bool purify)
	{
		BaseBattleActionData baseBattleActionData = (purify ? purifyAction.BaseBattleActionData : corruptAction.BaseBattleActionData);
		iconImage.sprite = baseBattleActionData.ActionSprite;
		shadowImage.sprite = baseBattleActionData.ActionSprite;
		if (amount == EffectsValues.INFINITY_PURIFY)
		{
			valueText.SetText("∞");
		}
		else
		{
			valueText.SetText(amount.ToString());
		}
		valueText.color = (baseBattleActionData.EnableColorReference ? baseBattleActionData.colorReference.Value : baseBattleActionData.ActionColor);
	}

	private void SpawnVFX(bool purify, Vector3 unitPosition)
	{
		GameObject vfxPrefab = (purify ? purifyVFX : corruptVFX);
		ReferenceSingleton<VFXHandler>.Instance.SpawnVFX(vfxPrefab, unitPosition.ZeroZ(), 2f);
		OnScreenShake.Raise(0.13f, 0.2f);
	}

	public void PlayBlockFeedback(bool purifyBlocked, int amountBlocked, Vector3 unitPosition, FeedbackDirectionEnum feedbackDirectionEnum)
	{
		SetupBlockFeedback(purifyBlocked, amountBlocked);
		PlayFeedback(unitPosition, feedbackDirectionEnum);
	}

	private void SetupBlockFeedback(bool purifyBlocked, int amountBlocked)
	{
		blockAmountFeedbackText.SetAlpha(1f);
		blockAmountFeedbackText.SetText(amountBlocked.ToString());
		valueText.SetText(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("Blocked"));
		BaseBattleActionData baseBattleActionData = (purifyBlocked ? purifyAction.BaseBattleActionData : corruptAction.BaseBattleActionData);
		iconImage.sprite = baseBattleActionData.ActionSprite;
		shadowImage.sprite = baseBattleActionData.ActionSprite;
		ReferenceSingleton<SFXHandler>.Instance.PlaySFX(purifyBlocked ? purifyBlockedSFX : corruptionBlockedSFX);
	}

	protected override void FadeSprites()
	{
		base.FadeSprites();
		if (blockFeedback)
		{
			StartCoroutine(blockAmountFeedbackText.FadeSprite(0f, fadeDuration, fadeCurve));
		}
	}

	private void PlayFeedback(Vector3 unitPosition, FeedbackDirectionEnum feedbackDirectionEnum)
	{
		PlayFeedback(unitPosition);
		Vector3 leftRightModifier = Vector3.zero;
		switch (feedbackDirectionEnum)
		{
		case FeedbackDirectionEnum.RIGHT:
			leftRightModifier = Vector3.right * Random.Range(leftRightMovementRangedFloat.minValue, leftRightMovementRangedFloat.maxValue);
			break;
		case FeedbackDirectionEnum.LEFT:
			leftRightModifier = Vector3.left * Random.Range(leftRightMovementRangedFloat.minValue, leftRightMovementRangedFloat.maxValue);
			break;
		}
		StartCoroutine(CoroutineUtility.CurveRoutine(movementDuration, movementCurve, delegate(float t, float v)
		{
			base.transform.position = base.transform.position + leftRightModifier * leftRightMovementCurve.Evaluate(t);
		}));
		Vector3 startScale = Vector3.one;
		Vector3 targetScale = Vector3.one * zoomAmount;
		StartCoroutine(CoroutineUtility.CurveRoutine(zoomDuration, zoomCurve, delegate(float t, float v)
		{
			base.transform.localScale = Vector3.Lerp(startScale, targetScale, v);
		}));
	}
}
